#include "household_transport_presence.hpp"
#include "movement_exact_detail.hpp"
#include "resident/storage/common_store.hpp"
namespace hanmo::resident {using namespace movement_detail;
Outcome<HouseholdSpatialPresence> read_household_purchase_presence(const CommonStore& common,const LocalEconomyState& economy,const PopulationTransportState& population,const SpatialCarrierState& carriers,const MovementExactState& movement,const SpatialCarrierSources& sources,const HouseholdPurchasePlan& plan,const StableId& place,const StableId& custody,const StableId& destination,const SourceRef& handling,const WorldMoment& at,ExactArithmeticBudget budget){return guard<HouseholdSpatialPresence>([&]{take(encode_world_moment(at,budget));if(plan.plan_id.empty()||destination!=plan.destination_inventory||!same_moment(at,take(sources.current_moment()),budget))fail("HouseholdPresencePlanMismatch");MovementAnchor anchor;SourceRef actual;
if(const auto* named=std::get_if<NamedHouseholdBuyer>(&plan.execution_choice)){const auto* actor=common.actor(named->actor_id);if(!actor||!actor->alive||!actor->available)fail("HouseholdBuyerUnavailable",named->actor_id);if(const auto* binding=movement.spatial_bindings.find("actor:"+named->actor_id)){anchor=take(read_carrier_movement_anchor(movement,ActorCarrierRef{named->actor_id},budget));actual=binding->binding_source;}else{anchor=take(sources.original_actor_anchor(named->actor_id));actual=std::visit([](const auto& value)->SourceRef{using T=std::decay_t<decltype(value)>;if constexpr(std::is_same_v<T,TerrainContinuousAnchor>)return value.actual_prefix_close_source;else return value.actual_source;},anchor);}}
else{const auto& buyer=std::get<CohortHouseholdBuyer>(plan.execution_choice);const auto* selection=population.selections.find(buyer.population_selection_ref);const auto* allocation=economy.labor_allocations.find(buyer.labor_allocation_id);const auto* cohort=economy.cohorts.find(buyer.cohort_id);if(!selection||selection->purpose!=PopulationSelectionPurpose::household_purchase||selection->state==PopulationSelectionPhase::released||selection->selected_persons!=1||selection->selected_labor_eligible!=1||buyer.workers!=1||!same_source(buyer.accepted_household_policy_ref,plan.accepted_policy_ref)||!allocation||allocation->cohort_id!=buyer.cohort_id||allocation->workers!=1||allocation->from_tick>at.half_day_tick||allocation->through_tick<at.half_day_tick||!cohort||cohort->household_group_id!=plan.household_id)fail("HouseholdCohortExecutionSourceRequired");if(selection->state==PopulationSelectionPhase::materialized){const auto* materialized=population.materializations.find(selection->id);if(!materialized||materialized->result_cohort_ref.cohort_id!=buyer.cohort_id)fail("HouseholdBuyerSelectionMismatch");}else if(selection->source.cohort_id!=buyer.cohort_id)fail("HouseholdBuyerSelectionMismatch");auto ref=take(read_civilian_population_ref(economy,population,buyer.cohort_id));auto location=take(read_population_location_source(economy,population,ref));actual=location.location_binding_ref;if(location.stationary_site_id)anchor=take(sources.original_site_anchor(*location.stationary_site_id));else if(ref.transport_binding_id)anchor=take(read_population_transport_anchor(economy,population,carriers,movement,*ref.transport_binding_id,budget));else fail("HouseholdBuyerSpatialBindingRequired");}
auto site=take(sources.original_site_anchor(place));auto cargo=take(read_inventory_spatial_anchor(common,carriers,movement,sources,custody,budget));if(!source_valid(actual)||!take(same_spatial_anchor(anchor,site,budget))||!take(same_spatial_anchor(cargo,site,budget)))fail("HouseholdBuyerNotAtActualMarket");auto reachability=take(read_storage_reachability(common,carriers,movement,sources,custody,destination,handling,budget));return HouseholdSpatialPresence{plan.plan_id,place,plan.execution_choice,at,anchor,cargo,actual,std::move(reachability)};});}
}
